--
-- Table structure for table `catalog_template_products`
--

DROP TABLE IF EXISTS `catalog_template_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `catalog_template_products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `catalog_template_id` bigint(20) unsigned NOT NULL,
  `category_name` varchar(100) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `sku` varchar(50) DEFAULT NULL,
  `barcode` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `unit` varchar(20) NOT NULL DEFAULT 'unité',
  `selling_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `cost_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tax_rate` decimal(5,2) NOT NULL DEFAULT 0.00,
  `alert_quantity` decimal(10,2) NOT NULL DEFAULT 5.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `catalog_template_products_catalog_template_id_foreign` (`catalog_template_id`),
  CONSTRAINT `catalog_template_products_catalog_template_id_foreign` FOREIGN KEY (`catalog_template_id`) REFERENCES `catalog_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

